// Actual article writes, canonical MariaDB and the real emailer/templates.
// Only the final mail transport is captured; mail() must remain disabled.
if(PHP_SAPI!=='cli'||getenv('PHPBB_KB_NOTIFY_NATIVE')!=='1'){echo "KB mail checks require explicitly enabled disposable storage.\n";return;}
if(!in_array('mail',array_map('trim',explode(',',ini_get('disable_functions'))),true)){throw new RuntimeException('Native KB mail requires disabled mail');}
putenv('PHPBB_KB_COUNTER_NATIVE=1');putenv('PHPBB_KB_COUNTER_PORT='.(getenv('PHPBB_KB_NOTIFY_PORT')?:'3306'));putenv('PHPBB_KB_COUNTER_PASSWORD='.(getenv('PHPBB_KB_NOTIFY_PASSWORD')?:''));
$kn_write_file=__DIR__.'/check-kb-writing-native.php';$kn_write_source=file_get_contents($kn_write_file);$kn_write_cut=strpos($kn_write_source,"require __DIR__.'/check-kb-publication-native.php';");if($kn_write_cut===false){throw new RuntimeException('Actual writing fixture boundary');}
$kn_head='';foreach(token_get_all(substr($kn_write_source,0,$kn_write_cut))as$t){$kn_head.=is_array($t)?($t[0]===T_DIR?var_export(__DIR__,true):$t[1]):$t;}eval(substr($kn_head,5));
function kn_prepare($language='english',$mode='add'){
 global$kp_source,$board_config,$lang;
 $lang=array();$caller=$language==='english'?'german':'english';require$kp_source.'language/lang_'.$caller.'/lang_main.php';require$kp_source.'language/lang_'.$caller.'/lang_kb.php';
 kw_reset('ordinary',false,'2');$GLOBALS['kn_fault']='';
 $board_config=array_merge($board_config,array('board_email'=>'cached@example.invalid','default_lang'=>$caller,'sitename'=>'Cached board','board_email_sig'=>'Cached signature','server_name'=>'forum.example.invalid','smtp_delivery'=>0,'sendmail_fix'=>0));
 foreach(array('board_email'=>'current@example.invalid','default_lang'=>$language,'sitename'=>'Current Grüße 😀 board','board_email_sig'=>'Current<br />Signature')as$key=>$value){kp_sql("INSERT INTO fixture_config(config_name,config_value) VALUES('".$key."','".$GLOBALS['peer']->sql_escape($value)."')");}
 $out=kw_ok(kw_run($mode),'Actual committed article before optional mail');kp_check($out['notify_email']&&(int)$out['approved']===($mode==='edit'?2:0),'Actual pending0/review2 outcome');return$out;
}
function kn_dispatch($out,$failure=0){
 global$kp_source,$phpbb_root_path,$board_config,$lang,$db,$kp_hook,$kn_queries,$kn_count,$kn_mail;
 $prior_config=$board_config;$prior_lang=$lang;$prior_db=$db;$kn_queries=$kn_mail=array();$kn_count=0;
 $kp_hook=function($phase,$sql,$owner)use($failure){if($phase!=='before'){return;}$GLOBALS['kn_queries'][]=$sql;return ++$GLOBALS['kn_count']===$failure?false:null;};$phpbb_root_path=__DIR__.'/../fixtures/kb-notifications-native/';
 try{$ok=kb_notify_after_write($out);}finally{$phpbb_root_path=$kp_source;$kp_hook=null;}
 kp_check($board_config===$prior_config&&$lang===$prior_lang&&$db===$prior_db,'Mail restores caller config/language/database on every path');
 foreach($GLOBALS['kp_owner_connections']as$owner){kp_check(!$owner->connection->db_connect_id,'All actual KB readers/writers closed');}
 foreach($kn_queries as$sql){kp_check(!preg_match('/^\s*(?:INSERT|UPDATE|DELETE|COMMIT)\b/i',$sql),'KB readiness never writes or commits');}
 return array('ok'=>$ok,'mail'=>$kn_mail,'sql'=>$kn_queries);
}
function kn_approve($id){$GLOBALS['userdata']['user_id']=1;kp_sql('UPDATE fixture_sessions SET session_user_id=1,session_admin=1');$out=kp_run(1,'acp',$id);kp_check(is_array($out)||$out===true,'Actual root approval after author commit');}
function kn_suite(){
 global$kp_source,$kn_app,$kn_fault,$board_config,$userdata,$peer,$db,$kp_factory;
 require$kp_source.'includes/functions_kb_write_storage.php';require$kp_source.'includes/functions_kb_write_notifications.php';$kn_app=$kp_source;$cases=$failures=0;
 foreach(array('english','german')as$language){
  foreach(array('add','edit')as$mode){foreach(array('ordinary','approved','deleted','renamed','notify-off','notify-pm','notify-missing','notify-invalid','address','address-invalid','cached-address-invalid','language','language-invalid','site','signature','actor-inactive','actor-deleted','actor-revoked','construct','template','transport-false','transport-exception','missing-settings','literal-title')as$kind){
   $out=kn_prepare($language,$mode);$title=$out['article_title'];$actual_language=$language;
   if($kind==='approved'){kn_approve($out['article_id']);}elseif($kind==='deleted'){kp_sql('DELETE FROM fixture_kb_articles WHERE article_id='.(int)$out['article_id']);}elseif($kind==='renamed'||$kind==='literal-title'){$input=kw_input();$title=$input['title']=$kind==='literal-title'?"Literal <br /> \\n &amp; Grüße 😀":"Current title changed Grüße 😀";kw_ok(kw_run('edit',$input,$out['article_id']),'Actual later title edit');}
   elseif($kind==='notify-off'||$kind==='notify-pm'||$kind==='notify-invalid'){kp_sql("UPDATE fixture_kb_config SET config_value='".($kind==='notify-off'?'0':($kind==='notify-pm'?'1':'invalid'))."' WHERE config_name='notify'");}elseif($kind==='notify-missing'){kp_sql("DELETE FROM fixture_kb_config WHERE config_name='notify'");}
   elseif($kind==='address'||$kind==='address-invalid'){kp_sql("UPDATE fixture_config SET config_value='".($kind==='address'?'changed@example.invalid':'invalid')."' WHERE config_name='board_email'");}elseif($kind==='cached-address-invalid'){$board_config['board_email']='invalid';}
   elseif($kind==='language'||$kind==='language-invalid'){$actual_language=$kind==='language'?($language==='english'?'german':'english'):'english';kp_sql("UPDATE fixture_config SET config_value='".($kind==='language'?$actual_language:'../invalid')."' WHERE config_name='default_lang'");}
   elseif($kind==='site'){kp_sql("UPDATE fixture_config SET config_value='Renamed Grüße 😀 board' WHERE config_name='sitename'");}elseif($kind==='signature'){kp_sql("UPDATE fixture_config SET config_value='Changed<br />Signature' WHERE config_name='board_email_sig'");}
   elseif($kind==='actor-inactive'){kp_sql('UPDATE fixture_users SET user_active=0 WHERE user_id=4');}elseif($kind==='actor-deleted'){kp_sql('DELETE FROM fixture_users WHERE user_id=4');}elseif($kind==='actor-revoked'){kp_sql('DELETE FROM fixture_sessions');}
   elseif(in_array($kind,array('construct','template','transport-false','transport-exception'),true)){$kn_fault=$kind;}elseif($kind==='missing-settings'){kp_sql("DELETE FROM fixture_config WHERE config_name='sitename'");}
   $before=kp_snapshot();$result=kn_dispatch($out);$error=in_array($kind,array('notify-missing','notify-invalid','address-invalid','construct','template','transport-false','transport-exception','missing-settings'),true);$capture=!in_array($kind,array('approved','deleted','notify-off','notify-pm','notify-missing','notify-invalid','address-invalid','construct','template','missing-settings'),true);
   kp_check($result['ok']===!$error&&count($result['mail'])===($capture?1:0)&&kp_snapshot()===$before,'Current KB notice '.$language.'/'.$mode.'/'.$kind.'; durable data unchanged');
   if($capture){$mail=$result['mail'][0];$tpl=file_get_contents($kp_source.'language/lang_'.$actual_language.'/email/kb_pending_article.tpl');kp_check(preg_match('/^Subject: ([^\r\n]+)/',$tpl,$m)===1&&$mail['subject']===$m[1],'Actual board-language template subject independent of caller');kp_check($mail['to']===($kind==='address'?'changed@example.invalid':'current@example.invalid'),'Current board email rather than stale cached address');kp_check($mail['vars']['ARTICLE_TITLE']===$title&&strpos($mail['body'],$title)!==false,'Current exact title including literal markup/entities');kp_check($mail['vars']['SITENAME']===($kind==='site'?'Renamed Grüße 😀 board':'Current Grüße 😀 board'),'Current board name');kp_check($mail['vars']['EMAIL_SIG']===($kind==='signature'?"Changed\nSignature":"Current\nSignature"),'Plain-text current board signature');kp_check($mail['vars']['U_REVIEW']==='https://forum.example.invalid/admin/admin_kb_art.php','Fresh ACP entry URL without stale session token');kp_check(strpos($mail['body'],$actual_language==='german'?'wartet ein Artikel':'An article is awaiting')!==false,'Actual body language matches current board');if($kind!=='literal-title'){kp_check(strpos($mail['body'],'<br />')===false&&strpos($mail['body'],'\\n')===false,'No HTML breaks or literal escaped newlines in plain mail');}}$cases++;
  }}
  foreach(array('normal','missing','borrow')as$factory){$out=kn_prepare($language);$r=$db->sql_query('START TRANSACTION');kp_check($r,'Caller snapshot');$r=$db->sql_query('SELECT article_title FROM fixture_kb_articles WHERE article_id='.(int)$out['article_id']);$old=$db->sql_fetchrow($r);$db->sql_freeresult($r);kp_sql("UPDATE fixture_kb_articles SET article_title='Fresh after caller snapshot' WHERE article_id=".(int)$out['article_id']);$kp_factory=$factory;
   try{$before=kp_snapshot();$result=kn_dispatch($out);$r=$db->sql_query('SELECT article_title,@@SESSION.in_transaction active_transaction FROM fixture_kb_articles WHERE article_id='.(int)$out['article_id']);$still=$db->sql_fetchrow($r);$db->sql_freeresult($r);kp_check($result['ok']===($factory==='normal')&&count($result['mail'])===($factory==='normal'?1:0)&&$still['article_title']===$old['article_title']&&(int)$still['active_transaction']===1&&kp_snapshot()===$before,'Independent reader/refused factory never adopts, commits or closes caller');if($factory==='normal'){kp_check($result['mail'][0]['vars']['ARTICLE_TITLE']==='Fresh after caller snapshot','Current title ignores caller repeatable snapshot');}$cases++;}finally{$kp_factory='normal';$db->sql_query('ROLLBACK');}
  }
  foreach(array('fixture_kb_articles','fixture_kb_config','fixture_config')as$table){$out=kn_prepare($language);kp_sql('ALTER TABLE '.$table.' ENGINE=MyISAM');try{$before=kp_snapshot();$result=kn_dispatch($out);kp_check(!$result['ok']&&!$result['mail']&&kp_snapshot()===$before,'Legacy participant cannot send or undo article');$cases++;}finally{kp_sql('ALTER TABLE '.$table.' ENGINE=InnoDB ROW_FORMAT=DYNAMIC');}}
  $out=kn_prepare($language);$out['notify_email']=false;$result=kn_dispatch($out,1);kp_check($result['ok']&&!$result['mail']&&!$result['sql'],'Disabled committed outcome creates no read owner');$cases++;
  $out=kn_prepare($language);$out['article_id']=array(1);$result=kn_dispatch($out);kp_check(!$result['ok']&&!$result['mail']&&!$result['sql'],'Complete typed article identity rejected before reader');$cases++;
  $out=kn_prepare($language);$reference=kn_dispatch($out);$positions=array();$seen=array();$index=0;foreach($reference['sql']as$sql){$index++;$kind=null;if($index<=3){$kind='initial-'.$index;}elseif($sql==='START TRANSACTION READ ONLY'){$kind='start';}elseif(strpos($sql,'information_schema.TABLES')!==false){$kind='metadata';}elseif(strpos($sql,'SELECT article_id,article_title,approved')===0){$kind='article';}elseif(strpos($sql,'SELECT config_value FROM')===0){$kind='notify';}elseif(strpos($sql,'SELECT config_name,config_value FROM')===0){$kind='board';}if($kind!==null&&!isset($seen[$kind])){$seen[$kind]=true;$positions[]=$index;}}
  foreach($positions as$position){$before=kp_snapshot();$result=kn_dispatch($out,$position);kp_check(!$result['ok']&&!$result['mail']&&kp_snapshot()===$before,'Optional readiness SQL failure leaves saved article unchanged');$failures++;}
 }
 echo 'KB notifications native: '.$cases.' cases, '.$failures." SQL failures PASS; actual committed articles and approvals, real EN/DE mailer/templates, current pending state and board settings, plain text, caller isolation and released locks.\n";
}
$kn_publication_file=__DIR__.'/check-kb-publication-native.php';$kn_publication=file_get_contents($kn_publication_file);$kn_anchor='if(!empty($kp_write_mode)){kp_write_suite();return;}';if(substr_count($kn_publication,$kn_anchor)!==1){throw new RuntimeException('Actual canonical setup suite boundary');}$kn_publication=str_replace($kn_anchor,'if(!empty($kp_write_mode)){kn_suite();return;}',$kn_publication);$kn_anchor='if(!empty($kp_write_mode)){$kp_tables=array_merge($kp_tables,array(PRIVMSGS_TABLE,PRIVMSGS_TEXT_TABLE));}';if(substr_count($kn_publication,$kn_anchor)!==1){throw new RuntimeException('Canonical board config participant boundary');}$kn_publication=str_replace($kn_anchor,$kn_anchor.'$kp_tables=array_unique(array_merge($kp_tables,array(CONFIG_TABLE)));',$kn_publication);$kn_eval='';foreach(token_get_all($kn_publication)as$t){$kn_eval.=is_array($t)?($t[0]===T_DIR?var_export(__DIR__,true):$t[1]):$t;}eval(substr($kn_eval,5));
